/// The code in an error answer, {error:{code,message},requestId}, and its HTTP status. unauthorized (a bad hook key), paused (a paused hook), badDeliveryId and full (its queue) come from the computer's relay, on /v1/hooks only.
public enum CloudErrorCode: String, Sendable {
    case badRequest
    case badDeliveryId
    case unauthenticated
    case badSignature
    case unauthorized
    case forbidden
    case accountDeleted
    case notFound
    case unknownComputer
    case alreadyClaimed
    case conflict
    case staleEpoch
    case stalePause
    case removed
    case tooMany
    case inviteUsed
    case paused
    case claimExpired
    case requestExpired
    case inviteExpired
    case inviteRevoked
    case tooLarge
    case upgradeRequired
    case rateLimited
    case full
    case `internal`
    case screenRelayUnavailable
    /// A code this version doesn't know.
    case unknown

    public init(code: String) {
        self = Self(rawValue: code) ?? .unknown
    }

    public var status: Int? {
        switch self {
        case .badRequest: 400
        case .badDeliveryId: 400
        case .unauthenticated: 401
        case .badSignature: 401
        case .unauthorized: 401
        case .forbidden: 403
        case .accountDeleted: 403
        case .notFound: 404
        case .unknownComputer: 404
        case .alreadyClaimed: 409
        case .conflict: 409
        case .staleEpoch: 409
        case .stalePause: 409
        case .removed: 409
        case .tooMany: 409
        case .inviteUsed: 409
        case .paused: 409
        case .claimExpired: 410
        case .requestExpired: 410
        case .inviteExpired: 410
        case .inviteRevoked: 410
        case .tooLarge: 413
        case .upgradeRequired: 426
        case .rateLimited: 429
        case .full: 429
        case .internal: 500
        case .screenRelayUnavailable: 503
        case .unknown: nil
        }
    }
}

extension CloudContract {
    /// Decodes `data` as the contract type `name`; false when the contract has no such type. For the fixtures' tests.
    public static func decode(_ name: String, _ data: Data) throws -> Bool {
        let d = JSONDecoder()
        switch name {
        case "EmptyAnswer": _ = try d.decode(EmptyAnswer.self, from: data)
        case "OkAnswer": _ = try d.decode(OkAnswer.self, from: data)
        case "Health": _ = try d.decode(Health.self, from: data)
        case "Me": _ = try d.decode(Me.self, from: data)
        case "RegisterDevice": _ = try d.decode(RegisterDevice.self, from: data)
        case "RegisteredDevice": _ = try d.decode(RegisteredDevice.self, from: data)
        case "DeviceRegistered": _ = try d.decode(DeviceRegistered.self, from: data)
        case "CloudDevice": _ = try d.decode(CloudDevice.self, from: data)
        case "DeviceList": _ = try d.decode(DeviceList.self, from: data)
        case "ClaimChallenge": _ = try d.decode(ClaimChallenge.self, from: data)
        case "CompleteClaim": _ = try d.decode(CompleteClaim.self, from: data)
        case "CloudComputer": _ = try d.decode(CloudComputer.self, from: data)
        case "ComputerClaimed": _ = try d.decode(ComputerClaimed.self, from: data)
        case "ComputerList": _ = try d.decode(ComputerList.self, from: data)
        case "RenameComputer": _ = try d.decode(RenameComputer.self, from: data)
        case "ComputerRenamed": _ = try d.decode(ComputerRenamed.self, from: data)
        case "CreateAccessRequest": _ = try d.decode(CreateAccessRequest.self, from: data)
        case "AccessRequestCreated": _ = try d.decode(AccessRequestCreated.self, from: data)
        case "AccessStatus": _ = try d.decode(AccessStatus.self, from: data)
        case "Reveal": _ = try d.decode(Reveal.self, from: data)
        case "CloudGrant": _ = try d.decode(CloudGrant.self, from: data)
        case "GrantList": _ = try d.decode(GrantList.self, from: data)
        case "HostRegister": _ = try d.decode(HostRegister.self, from: data)
        case "HostRegistered": _ = try d.decode(HostRegistered.self, from: data)
        case "Owner": _ = try d.decode(Owner.self, from: data)
        case "HostGrant": _ = try d.decode(HostGrant.self, from: data)
        case "HostAccessRequest": _ = try d.decode(HostAccessRequest.self, from: data)
        case "Membership": _ = try d.decode(Membership.self, from: data)
        case "BotDevice": _ = try d.decode(BotDevice.self, from: data)
        case "HostState": _ = try d.decode(HostState.self, from: data)
        case "HostContact": _ = try d.decode(HostContact.self, from: data)
        case "PeerComputer": _ = try d.decode(PeerComputer.self, from: data)
        case "PeerComputerList": _ = try d.decode(PeerComputerList.self, from: data)
        case "CreatePeerRequest": _ = try d.decode(CreatePeerRequest.self, from: data)
        case "HostPeerRequest": _ = try d.decode(HostPeerRequest.self, from: data)
        case "HostPeer": _ = try d.decode(HostPeer.self, from: data)
        case "ScreenIceRequest": _ = try d.decode(ScreenIceRequest.self, from: data)
        case "IceServer": _ = try d.decode(IceServer.self, from: data)
        case "IceConfig": _ = try d.decode(IceConfig.self, from: data)
        case "HostNonce": _ = try d.decode(HostNonce.self, from: data)
        case "HostDecision": _ = try d.decode(HostDecision.self, from: data)
        case "Decided": _ = try d.decode(Decided.self, from: data)
        case "CreateInvite": _ = try d.decode(CreateInvite.self, from: data)
        case "PersonRevoke": _ = try d.decode(PersonRevoke.self, from: data)
        case "PersonRevoked": _ = try d.decode(PersonRevoked.self, from: data)
        case "ContactPerson": _ = try d.decode(ContactPerson.self, from: data)
        case "DirectoryDevice": _ = try d.decode(DirectoryDevice.self, from: data)
        case "DirectoryComputer": _ = try d.decode(DirectoryComputer.self, from: data)
        case "ContactDirectory": _ = try d.decode(ContactDirectory.self, from: data)
        case "Contact": _ = try d.decode(Contact.self, from: data)
        case "ContactList": _ = try d.decode(ContactList.self, from: data)
        case "PcRecipient": _ = try d.decode(PcRecipient.self, from: data)
        case "PcSend": _ = try d.decode(PcSend.self, from: data)
        case "PcSent": _ = try d.decode(PcSent.self, from: data)
        case "PcInboxItem": _ = try d.decode(PcInboxItem.self, from: data)
        case "PcInbox": _ = try d.decode(PcInbox.self, from: data)
        case "PcAck": _ = try d.decode(PcAck.self, from: data)
        case "ContactEpoch": _ = try d.decode(ContactEpoch.self, from: data)
        case "ContactChanged": _ = try d.decode(ContactChanged.self, from: data)
        case "AcceptInvite": _ = try d.decode(AcceptInvite.self, from: data)
        case "InviteAccepted": _ = try d.decode(InviteAccepted.self, from: data)
        case "AcceptBotInvite": _ = try d.decode(AcceptBotInvite.self, from: data)
